function download(blob,name){const a=el('a',{href:URL.createObjectURL(blob),download:name});document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),3000);}
const PERSON_HEADERS=['ПІБ','Позивний','Звання','Посада','Підрозділ','Телефон','Група','На службі з','Примітки','Категорія'];
