function importPeople(){pickFile('.xlsx,.csv',async file=>{const rows=file.name.toLowerCase().endsWith('.csv')?csvRows(await file.text()):await readWorkbook(file);const headers=(rows.shift()||[]).map(v=>String(v).trim().toLocaleLowerCase('uk'));const indices=PERSON_HEADERS.map((h,i)=>headers.findIndex(v=>v===h.toLocaleLowerCase('uk')||v===PERSON_KEYS[i]));if(indices[0]<0)throw Error('Перший аркуш має містити колонку «ПІБ». Завантажте шаблон через «Експорт Excel».');if(rows.length>3000)throw Error('Ліміт імпорту — 3000 людей.');const seenNames=new Set(state.people.map(p=>p.name.trim().replace(/\s+/g,' ').toLocaleLowerCase('uk'))),seenCalls=new Set(state.people.map(p=>p.callsign.toLocaleLowerCase('uk')).filter(Boolean));const imported=rows.filter(r=>r.some(Boolean)).map(row=>{const p=Object.fromEntries(PERSON_KEYS.map((k,i)=>[k,String(row[indices[i]]??'').trim()]));p.category=p.category||CATEGORIES[0];if(/^\d{5}(\.\d+)?$/.test(p.service_since))p.service_since=daystr(Math.floor(Number(p.service_since))-25569);let reason='';const normalized=p.name.replace(/\s+/g,' ').toLocaleLowerCase('uk'),calls=p.callsign.toLocaleLowerCase('uk');if(!p.name)reason='Немає ПІБ';else if(seenNames.has(normalized))reason='ПІБ уже існує';else if(calls&&seenCalls.has(calls))reason='Позивний уже існує';else if(p.service_since&&(!/^\d{4}-\d{2}-\d{2}$/.test(p.service_since)||!Number.isFinite(daynum(p.service_since))||daystr(daynum(p.service_since))!==p.service_since))reason='Некоректна дата';seenNames.add(normalized);if(calls)seenCalls.add(calls);return {person:{id:uid(),archived:false,...p},reason};});const valid=imported.filter(v=>!v.reason);const err=errorBox();modal('Попередній перегляд імпорту',el('div',{},el('div',{class:'note'},`Нових людей: ${valid.length}. Пропущено повторів або помилок: ${imported.length-valid.length}. Існуючі картки не перезаписуються. Нові посади та групи буде додано до довідників.`),el('div',{class:'import-preview'},table(['ПІБ','Позивний','Перевірка'],imported.map(v=>el('tr',{},el('td',{},v.person.name),el('td',{},v.person.callsign),el('td',{},badge(v.reason||'Буде додано',v.reason?'late':'fresh')))))),err),[btn('Імпортувати '+valid.length+' людей',async()=>{try{const next=structuredClone(state);for(const {person} of valid){for(const [key,value] of [['roles',person.role],['groups',person.group]])if(value&&!next[key].includes(value))next[key].push(value);next.people.push(person);}await save(next,'Імпорт людей з Excel / CSV: '+valid.length);MODAL.close();}catch(e){showError(err,e);}},'primary',!valid.length||user.role==='viewer')]);});}
function importBackup(){pickFile('.json',async file=>{const raw=JSON.parse(await file.text());if(raw.format!=='personnel-web-v2'||!raw.state)throw Error('Це не резервна копія кадрової вебверсії.');confirmAction('Відновити базу з файлу?',`Файл містить ${raw.state.people?.length||0} людей і ${raw.state.events?.length||0} кадрових подій. Поточні записи буде замінено, але перед зміною збережеться автоматична копія.`,async()=>{await save(raw.state,'Відновлення кадрової бази з JSON');});});}

function startStaticDemo(){
  demoMode=true;user={id:'demo',login:'Демо · перегляд',role:'viewer'};revision=0;today=new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Kyiv'}).format(new Date());
  state={admin_tasks:[],admin_log:[],classes:[],grades:[],people:[],events:[],groups:['Група 1','Група 2'],roles:['Адміністратор','Водій','Технік'],title:'Кадровий простір · вигадане демо'};
  for(let i=0;i<10;i++){const id='demo-'+i;state.people.push({id,name:'Тестова людина '+String(i+1).padStart(2,'0'),callsign:['Кедр','Клен','Риф','Дуб','Маяк','Бук','Атлас','Компас','Промінь','Берег'][i],rank:'',role:state.roles[i%3],unit:'Демонстраційна група',phone:'',group:state.groups[i%2],service_since:'2024-01-15',archived:false,notes:'Вигадана картка. Не використовуйте як реальні дані.'});for(const [j,[a,b,k]] of [[1,5,'Робота'],[10,14,i%3===0?'Відпустка':'Робота'],[20,24,i===5?'ВЛК':i===7?'Лікарняний':'Робота']].entries())state.events.push({id:'demo-'+i+'-'+j,person_id:id,kind:k,start:month+'-'+String(a).padStart(2,'0'),end:month+'-'+String(b).padStart(2,'0'),returned_on:'',cancelled:false,notes:'Вигаданий приклад'});}
  render();
}
const warehouseUI=shiftsUI({el,btn,field,select,modal,page,panel,table,empty,errorBox,showError,confirmAction,uid,notify,save,download,workbook,navigate,state:()=>state,today:()=>today,readonly:()=>user.role==='viewer',close:()=>MODAL.close()});
function updateChatBadge(count){chatUnread=count;const nav=document.querySelector('[data-nav="chat"]');if(nav){nav.querySelector('.chat-unread')?.remove();if(count)nav.append(el('span',{class:'chat-unread'},count>99?'99+':String(count)));}const option=document.querySelector('.mobile-nav option[value="chat"]');if(option)option.textContent='Чат адміністраторів'+(count?' · '+count:'');}
const chatUI=adminChat({el,btn,request,page,notify,user:()=>user,view:()=>view,time:profileTime,unread:updateChatBadge,access:allowed=>{if(chatAllowed!==allowed){chatAllowed=allowed;if(view==='chat'&&!allowed)view='overview';render();}}});
const extraUI=administrativeUI({el,btn,field,select,dateInput,calendarField,modal,confirmAction,page,panel,table,empty,badge,errorBox,showError,nice,uid,notify,save,request,filterBar,summary,filteredPeople,personNode,personReturnButton,personForm,eventForm,state:()=>state,today:()=>today,readonly:()=>user.role==='viewer',close:()=>MODAL.close(),refresh:render});
if(token){load().then(render).catch(e=>{auth();notify(e.message,true);});}else auth();

let synchronizing=false;setInterval(async()=>{if(!state||demoMode||saving||MODAL.open||document.hidden||synchronizing)return;synchronizing=true;try{const result=await request('state');if(result.revision!==revision){state=result.state;for(const key of EXTRA_TABLES)state[key]??=[];revision=result.revision;today=result.today;render();notify('Дані оновлено після змін іншого користувача.');}}catch{}finally{synchronizing=false;}},30000);
